using AcxiomCRM.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace AcxiomCRM.Controllers;[Authorize(Roles="Admin")]public class AuditController(AppDbContext db):Controller{public async Task<IActionResult> Index()=>View(await db.AuditLogs.AsNoTracking().OrderByDescending(x=>x.CreatedAt).Take(300).ToListAsync());}